"""Authenticate combined exact TSX-footer scope and existing legacy annual proof."""
import copy
from . import library,transcript_currentness as scope,legacy_equivalent_source as legacy
from .contracts import require
from .freshness import timestamp
VERSION='authenticated-tsx-app-rating-legacy-source-v1'
def verify_derivation(root,receipt,*,historical=False):
 d=receipt.get('derivation',{});require(set(d)=={'version','original_receipt','original_receipt_sha256','scoped_currentness','legacy_equivalence','manifest_path','manifest_sha256'} and d['version']==VERSION,'Exact combined TSX legacy derivation required');original_path=library.resolve(root,d['original_receipt']);require(scope.sha(original_path.read_bytes())==d['original_receipt_sha256'],'Original receipt changed');original=library.read_json(original_path);require('derivation'not in original and len(original['companies'])==1,'Original single issuer receipt required');proof=scope.replay(root,d['scoped_currentness'],historical=historical);require(proof['version']==scope.TSX_APP_RATING_VERSION and proof['issuer_id']==original['companies'][0]['issuer_id'],'Exact TSX scope proof required')
 ref=d['legacy_equivalence'];require(set(ref)=={'path','sha256'},'Exact annual proof binding required');path=library.resolve(root,ref['path']);require(scope.sha(path.read_bytes())==ref['sha256'],'Annual proof changed');annual=legacy.verify(root,path);row=original['companies'][0];require(annual['receipt_path']==d['original_receipt'] and annual['packet_id']==row['old_packet_id'],'Annual proof belongs to another receipt/packet')
 manifest=library.resolve(root,d['manifest_path']);require(scope.sha(manifest.read_bytes())==d['manifest_sha256'],'Derived manifest changed');expected_manifest=copy.deepcopy(annual['manifest']);expected_manifest['metadata'].update(equivalence_proof=ref['path'],equivalence_proof_sha256=ref['sha256']);require(library.read_json(manifest)==expected_manifest,'Derived manifest must preserve original qualification')
 expected=copy.deepcopy(original);row=expected['companies'][0];docs=[x for x in row['documents']if x['source_url']==proof['source_url']];require(len(docs)==1,'Unique transcript required');doc=docs[0];require(doc['status']=='changed_requires_review'and doc.get('scope_reason')=='Unsupported transcript publisher URL'and doc['expected_sha256']==proof['archived']['raw_sha256']and doc['observed_sha256']==proof['observed']['raw_sha256']and doc['raw_path']==proof['observed']['raw_path']and timestamp(doc['checked_at'])==proof['checked_at'],'Exact original TSX observation required');doc.update(status='scoped_transcript_currentness_verified',scoped_currentness=d['scoped_currentness']);doc.pop('scope_reason')
 docs=[x for x in row['documents']if x['document_id']==annual['document_id']];require(len(docs)==1,'Unique original annual required');doc=docs[0];require(doc['status']=='blocked'and doc.get('reason')=='No collector manifest for equivalent version','Exact original annual stop required');doc.update(status='identical_extracted_text_fiscal_tags_and_structured_facts',manifest_path=d['manifest_path']);doc.pop('reason');row['new_packet_id']=receipt['companies'][0]['new_packet_id'];expected['derivation']=d;require(expected==receipt,'Only authenticated transcript/annual status and new packet may change')
 return {d['original_receipt']:d['original_receipt_sha256'],ref['path']:ref['sha256'],d['manifest_path']:d['manifest_sha256'],**annual['input_sha256']}
